window.GRAPH = {"config": {"title": "Тот, кто остался", "start": "Т-00", "vars": {"ТЕЛ": {"start": 20, "min": 0, "max": 100, "name": "Тело", "tiers": [[0, "хилое"], [20, "обычное"], [40, "крепкое"], [60, "сильное"], [80, "железное"]]}, "РАЗ": {"start": 20, "min": 0, "max": 100, "name": "Разум", "tiers": [[0, "рассеянный"], [20, "обычный"], [40, "цепкий"], [60, "острый"], [80, "блестящий"]]}, "ЭМП": {"start": 20, "min": 0, "max": 100, "name": "Эмпатия", "tiers": [[0, "глухой к людям"], [20, "обычная"], [40, "чуткий"], [60, "тонкий"], [80, "видит насквозь"]]}, "ВОЛ": {"start": 20, "min": 0, "max": 100, "name": "Воля", "tiers": [[0, "робкий"], [20, "обычная"], [40, "упрямый"], [60, "твёрдый"], [80, "несгибаемый"]]}, "ДАР": {"start": 0, "min": 0, "max": 100, "name": "Резонанс", "tiers": [[0, "тишина"], [20, "холодок"], [40, "голоса"], [60, "хор"], [80, "регент"]]}, "ДРЕЙФ": {"start": 0, "min": 0, "max": 100, "name": "Дрейф", "hidden": true}, "СВЯЗЬ_НИКА": {"start": 0, "min": 0, "max": 100, "name": "Ника", "hidden": true}, "СВЯЗЬ_ВИТЬКА": {"start": 20, "min": 0, "max": 100, "name": "Витька", "hidden": true}, "СВЯЗЬ_МАМА": {"start": 40, "min": 0, "max": 100, "name": "Мама", "hidden": true}, "СВЯЗЬ_ОТЕЦ": {"start": 30, "min": 0, "max": 100, "name": "Отец", "hidden": true}}, "flags": {"F_Т01": {"type": "enum", "values": ["СПОР", "БУБЛИК", "ЧАСЫ", "ДОЛГ"]}, "F_Т02": {"type": "enum", "values": ["ЧЕЙ", "ХОР", "ЛИЦО", "МАМА"]}, "F_Т03": {"type": "enum", "values": ["ШРАМ", "ВОДЯНОЙ", "ЗАМЕТКА", "ВОДОБОЯЗНЬ"]}, "F_Т04": {"type": "enum", "values": ["РЕЛЬСЫ", "РЫНОК", "ЦВЕТМЕТ", "ОЛИМПИАДА"]}, "F_Т05": {"type": "enum", "values": ["ТЕТРАДИ", "ФОТО", "ПРОДАЛ", "СОЖЖЕНО"]}, "F_Т06": {"type": "enum", "values": ["ПЕРЕПЛЫЛ", "ТАЙНА_НИКИ", "ПАЦАНЫ", "БАКЕНЩИК"]}, "F_Т07": {"type": "enum", "values": ["КЛЮЧИ", "ЛЁД", "СДАЛ", "ВИДЕНИЕ"]}, "F_Т08": {"type": "enum", "values": ["ПАЛЫЧ", "ДОМ", "ТОРГ", "ДАТЧИКИ"]}, "F_Т09": {"type": "enum", "values": ["АРМИЯ", "ДОЛГ_СВАРНОМУ", "НИКА", "ДВЕРЬ"]}, "F_ПУТЬ": {"type": "enum", "values": ["ЛАМПА", "ПРОТОКОЛ", "ПАРТИЯ", "БАРАБАН", "ТЁПЛАЯ_ВОДА", "ХОР", "СЕМЬЯ"]}, "F_ЗНАЕТ": {"type": "bool"}, "F_НАПАРНИК_СЕРЁГА": {"type": "bool"}, "F_ОЖОГ_ЛЁГКИХ": {"type": "bool"}}, "rollback": [[0, 1], [20, 2], [40, 3], [60, 4], [80, 5]], "seal_groups": {"prologue": "trunk", "trunk": "trunk", "demo": "demo", "branch": "branch", "anchor": "anchor", "final": "final"}, "stihii": ["ВОДА", "ХОЛОД", "ОГОНЬ", "ВОЗДУХ", "ПОРОДА", "ЛЮДИ", "ДОРОГА"], "photo_eras": {"bw": "старое чёрно-белое фото, 1990-е", "color": "цветной глянец из фотомастерской, 2000-е", "digital": "цифровая мыльница, 2010-е", "phone": "смартфон, 2020–2040-е", "future": "слишком чистая картинка будущего, 2050–2061"}}, "scenes": {"Д-00": {"id": "Д-00", "title": "Демо. «Глубокая»", "date": "осень 2009", "age": 20, "stage": "demo", "photo": "color", "photo_caption": "«Глубокая», АБК. 2009", "photo_prompt": "glossy color photo print from 2009 with orange date stamp in the corner, first-person view, a soviet-era coal mine administrative building in Kemerovo, grey sky, miners in orange helmets smoking near the entrance, slightly faded colors", "text": [{"md": "Это демо механики смерти и отката, а не канон. Настоящая ветвь «Лампа» будет написана позже.", "kind": "sys"}, {"md": "Мне двадцать. Я хожу в забой на «Глубокую», в одну смену с батей. Каждое утро ламповщица Таня выдаёт мне лампу и самоспасатель и говорит одно и то же: «Принёс обратно — молодец». Я каждый раз отвечаю: «А если не принесу?» — и каждый раз получаю журналом выдачи по каске."}, {"md": "Про девяносто шестой я почти не вспоминаю. Иногда только просыпаюсь ровно в четыре двенадцать и лежу, слушаю, как отец за стенкой курит на балконе. Он тоже встаёт в это время. Мы про это не разговариваем, у Самохиных вообще не принято разговаривать."}, {"md": "За два года в забое человек меняется. Каким стал я?"}], "file": "D-00.md", "choices": [{"id": "A", "label": "Здоровым, как лось: турник во дворе, кайло, по выходным на разгрузку вагонов", "fx": [["add", "ТЕЛ", 30]], "outcomes": [{"to": "Д-01"}]}, {"id": "B", "label": "Головастым: заочка в горном, конспекты в бытовке, все инструкции наизусть", "fx": [["add", "РАЗ", 25], ["add", "ТЕЛ", 5]], "outcomes": [{"to": "Д-01"}]}, {"id": "C", "label": "Странным: ночами сижу на берегу заводи и слушаю, как она молчит", "fx": [["add", "ДАР", 30]], "outcomes": [{"to": "Д-01"}]}]}, "Д-01": {"id": "Д-01", "title": "Чёрная вода", "date": "14 ноября 2009, 04:12", "age": 20, "stage": "demo", "photo": "color", "photo_caption": "(кадр не сохранился)", "photo_prompt": "glossy color photo print with orange date stamp, first-person view, coal face in a mine lit by a single headlamp, black glittering coal wall, a gloved hand on a pneumatic pick, coal dust in the air, dark, slightly blurred", "text": [{"md": "Забой гудит, как пустая бочка. Я долблю пласт, Михалыч за спиной кидает уголь на конвейер и в третий раз за смену рассказывает анекдот про тёщу и парашют. Смеюсь я тоже в третий раз, из уважения к стажу."}, {"md": "Потом пласт вздыхает. Звука нет, просто стена передо мной делает вдох. Лампа выхватывает трещину, и трещина бежит вверх, быстро, как молния наоборот. Михалыч замолкает на полуслове. Впереди в темноте начинает шуршать, ровно и мощно, как песок в огромных часах."}, {"md": "— Выброс, — говорит Михалыч тихо и очень спокойно."}, {"md": "От этого спокойствия у меня отнимаются ноги."}], "file": "D-01.md", "choices": [{"id": "A", "label": "Бежать назад по штреку", "fx": [], "outcomes": [{"to": "✝Д-01.A"}]}, {"id": "B", "label": "Упасть на почву, закрыть голову руками", "fx": [], "outcomes": [{"to": "✝Д-01.B"}]}, {"id": "C", "label": "Вцепиться в стойку крепи и держаться", "fx": [], "outcomes": [{"to": "✝Д-01.C"}]}, {"id": "D", "label": "«Я это уже видел». Не к выходу, а в нишу за трансформатором, и тащить Михалыча за собой", "fx": [["set", "F_ЗНАЕТ", true], ["add", "ДАР", 5]], "outcomes": [{"to": "Д-02"}], "visible": {"op": "or", "a": [{"op": "seen", "id": "✝Д-01.A", "life": true}, {"op": "seen", "id": "✝Д-01.B", "life": true}, {"op": "seen", "id": "✝Д-01.C", "life": true}]}, "visible_src": "seen_life(✝Д-01.A) || seen_life(✝Д-01.B) || seen_life(✝Д-01.C)"}]}, "Д-02": {"id": "Д-02", "title": "Метан", "date": "3 марта 2012, 04:12", "age": 23, "stage": "demo", "photo": "digital", "photo_caption": "Штрек. Снято на телефон, которым нельзя снимать в шахте", "photo_prompt": "early 2010s digital point-and-shoot photo, noisy, first-person view, a long dark coal mine drift with rails, a single headlamp beam, a gas detector on a belt glowing red, far behind a second miner's lamp, high ISO noise", "text": [{"md": "Три года я никому про это не рассказывал. Михалыч тоже молчит. Тогда, в ноябре, я за секунду до выброса затащил его в нишу за трансформатором, и теперь он смотрит на меня, как на икону, в которую не очень верит. На Пасху принёс мне кулич, положил на стол в бытовке и долго не уходил."}, {"md": "Умереть у меня, оказывается, не получается. Получается запомнить, как умирал, и с этим потом жить."}, {"md": "Датчик на поясе начинает пищать, и я понимаю, что это не глюк, ещё до того, как гаснет свет. Вентиляция встала, в лаве становится очень тихо. Метрах в сорока сзади матерится Серёга, фонарь у него мечется по стенам."}, {"md": "Метан не пахнет. Это первое, что говорят на курсах, и единственное, что я сейчас помню. До ствола восемьсот метров по главному штреку. Справа старая сбойка, наполовину заваленная породой."}, {"md": "В затылке холодеет, будто сзади кто-то стоит и дышит мне в шею. Кто-то, кто уже стоял на этом месте и дальше не пошёл.", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 20}}}], "file": "D-02.md", "choices": [{"id": "A", "label": "Бежать к стволу по главному штреку", "fx": [], "outcomes": [{"to": "Д-03", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ТЕЛ"}, "r": {"op": "num", "v": 45}}, "if_src": "ТЕЛ >= 45", "fx": [["add", "ТЕЛ", 5]]}, {"to": "✝Д-02.A"}]}, {"id": "B", "label": "Включить самоспасатель, уйти в сбойку и ждать", "fx": [], "outcomes": [{"to": "Д-03", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "РАЗ"}, "r": {"op": "num", "v": 40}}, "if_src": "РАЗ >= 40", "fx": [["add", "РАЗ", 5]]}, {"to": "✝Д-02.B"}]}, {"id": "C", "label": "Вернуться за Серёгой", "fx": [], "outcomes": [{"to": "Д-03", "if": {"op": "and", "a": [{"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ТЕЛ"}, "r": {"op": "num", "v": 45}}, {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ЭМП"}, "r": {"op": "num", "v": 25}}]}, "if_src": "ТЕЛ >= 45 && ЭМП >= 25", "fx": [["add", "ЭМП", 5]]}, {"to": "✝Д-02.C"}]}, {"id": "D", "label": "Прислушаться к тому, кто дышит в затылок", "fx": [["add", "ДАР", 5], ["add", "ДРЕЙФ", 5]], "outcomes": [{"to": "Д-03"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 25}}, "visible_src": "ДАР >= 25"}, {"id": "E", "label": "Лечь на почву, натянуть мокрую куртку на лицо и ждать", "fx": [["add", "ТЕЛ", -10], ["set", "F_ОЖОГ_ЛЁГКИХ", true]], "outcomes": [{"to": "Д-03"}]}]}, "Д-03": {"id": "Д-03", "title": "Конец демо", "date": "3 марта 2012", "age": 23, "stage": "demo", "photo": "digital", "photo_caption": "На-гора", "photo_prompt": "early 2010s digital photo, first-person view, grey dawn sky over coal mine headframe, snow, miners' faces black with coal dust, steam from breath", "text": [{"md": "Нас поднимают через шесть часов. Я дышу, как старый насос, и каждый вдох дерёт грудь изнутри. Врач в медпункте говорит: «Ожог дыхательных путей, жить будешь». Я киваю. Про «жить буду» он даже не представляет, насколько прав.", "if": {"op": "truthy", "n": "F_ОЖОГ_ЛЁГКИХ"}}, {"md": "На-гора уже светло, снег на копре розовый от рассвета. Серёга сидит на лавке у АБК, курит, хотя курить ему сейчас нельзя ни при каких обстоятельствах, и мелко смеётся без остановки.", "if": {"op": "not", "a": {"op": "truthy", "n": "F_ОЖОГ_ЛЁГКИХ"}}}, {"md": "Таня-ламповщица забирает у меня лампу и держит её в руках дольше обычного."}, {"md": "— Принёс обратно, — говорит она. — Молодец."}, {"md": "Я не говорю ей, что в каком-то другом мире она сейчас стоит у стойки с лампами и смотрит на пустой крючок с моим номером. Я и сам не знаю, откуда это знаю."}, {"md": "Конец демо. Загляни в «Хор»: там все, кем ты успел побыть. Потом начни новую жизнь и попробуй умереть иначе.", "kind": "sys"}], "file": "D-03.md"}, "Ж-00": {"id": "Ж-00", "title": "Эта жизнь ещё пишется", "date": "2007", "age": 18, "stage": "demo", "photo": "digital", "photo_caption": "(плёнка не проявлена)", "photo_prompt": "early digital camera photo, almost black, a blurry silhouette walking away along railway tracks at dawn, heavy noise", "text": [{"md": "Томск, физфак, общага на Ленина, минус сорок, и Томь там та же, только ниже по течению. Там я узнаю, кем был мой дед. Человек, который мне это расскажет, скажет мне «я тебя ждал».", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_ПУТЬ"}, "r": {"op": "lit", "v": "ПРОТОКОЛ"}}}, {"md": "Горная Шория, Мрассу, энцефалитные клещи и звёзды, каких в городе не бывает. Мальчик, который утонул в реке, уходит туда, где воды нет, один камень и мерзлота.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_ПУТЬ"}, "r": {"op": "lit", "v": "ПАРТИЯ"}}}, {"md": "Копанки под Киселёвском, долги, подпольный клуб в Новокузнецке и игра под названием «Барабан». Там я пойму, что смерть можно продавать. Так себе открытие.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_ПУТЬ"}, "r": {"op": "lit", "v": "БАРАБАН"}}}, {"md": "Новосибирск, потом Паттайя, потом море, где вода тёплая. Я научусь учить людей дышать под водой. О деде не узнаю никогда.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_ПУТЬ"}, "r": {"op": "lit", "v": "ТЁПЛАЯ_ВОДА"}}}, {"md": "Областная психиатрическая, Алтай, скит на верхней Мрассу. Голоса у меня в голове говорят правду, и от этого не легче.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_ПУТЬ"}, "r": {"op": "lit", "v": "ХОР"}}}, {"md": "«Азот», ипотека, «Гранта», дача в Ягуновском, дочка. Самая обычная жизнь, и в ней страшнее всего.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_ПУТЬ"}, "r": {"op": "lit", "v": "СЕМЬЯ"}}}, {"md": "Эта жизнь ещё пишется. Сейчас готово демо механики смерти и отката: жизнь шахтёра на «Глубокой». Можно пройти его, а можно начать новую жизнь через меню «Я».", "kind": "sys"}], "file": "J-00.md", "choices": [{"id": "A", "label": "Пройти демо: «Глубокая», 2009", "fx": [], "outcomes": [{"to": "Д-00"}]}]}, "Т-00": {"id": "Т-00", "title": "Пролог. Сухое русло", "date": "28 июля 2061, 03:42", "age": 72, "stage": "prologue", "photo": "future", "photo_caption": "Русло Томи. 2061", "photo_prompt": "first-person view, night, dry stone riverbed of a wide Siberian river, a perfectly round black pond full to the brim in the middle, a white bleached snag sticking out of the water like a hand, a bright comet with a long tail above, hyper-clean ultra-sharp image, unnaturally perfect, no people", "text": [{"md": "Томь ушла третьим летом подряд. Там, где в девяносто шестом я боялся заплывать за буйки, теперь ходят пешком. Камни, ржавая «копейка» вверх колёсами, пыль белая, как мука из гуманитарки. От Кемерова до самого Томска русло сухое, и по фарватеру гуляют с собаками."}, {"md": "А заводь стоит. Круглая, метров сорок поперёк, полная до краёв и чёрная. Учёные из Томска три лета гоняли по ней сонары и в отчёте написали, что дна нет. Могли бы сэкономить грант и спросить меня. Дно есть, я на нём лежал."}, {"md": "Над руслом висит комета. Хвост лёг точно вдоль реки, хоть по нему сверяй направление. В одиннадцатом классе астрономичка пообещала нам эту комету: «Вам будет по семьдесят два. Доживёте — посмотрите». Я дожил, Галина Ивановна. Смотрю."}, {"md": "Сколько раз я умирал, честно не помню. Это помнят они. Перед рассветом их почти не слышно, только шуршат, как бабкин «Рекорд» после конца эфира."}, {"md": "Коряга торчит на прежнем месте, белая и гладкая, растопыренная, как пятерня. Семьдесят два года назад я за неё не удержался."}, {"md": "Без восемнадцати четыре. До рассвета есть время рассказать всё по порядку, с того июля, когда мне было семь и я ещё ни разу не умирал."}], "file": "T-00.md", "next": "Т-01"}, "Т-01": {"id": "Т-01", "title": "Чёрная заводь", "date": "28 июля 1996", "age": 7, "stage": "trunk", "photo": "bw", "photo_caption": "Витька, Ника и Бублик. Лето 96-го", "photo_prompt": "old black-and-white family photo, 1996, first-person view from a 7-year-old, river bank with flat slate stones, a freckled boy of 8 pulling off his t-shirt, a serious girl of 7 in a panama hat holding a ginger puppy, dark still water behind, a white snag like a hand in the distance, grain, scratches, white border", "text": [{"md": "Летом девяносто шестого во дворе пахнет гудроном и тополиным пухом, а ещё углём, потому что углём у нас пахнет всё. Даже у мамы волосы пахнут углём, когда она приходит со смены с обогатительной. Мне семь лет. У меня есть полвелика (это «Кама» без одной педали, вторая половина Витькина), вкладыш от «Турбо» с красной «Ламборгини» и целое лето впереди."}, {"md": "На Чёрную заводь ходить нельзя. Бабка с первого этажа говорит, что там в восемьдесят каком-то утонул пацан с Шахтёрской и его так и не нашли, потому что там сваи и водяной. Витька говорит, что водяного не бывает, а сваи бывают, и они засасывают. Поэтому мы ходим именно туда."}, {"md": "Нас трое. Витька на год старше, рыжий в крапинку, орёт громче всех во дворе и врёт, что плавает как дельфин. Дельфинов он видел по телеку. Ника — его двоюродная сестра из Новосибирска, её привезли к нам на всё лето «подышать». Мама говорит, что у нас не воздух, а пыль с химией, но Нике нравится. У неё панамка с вишнями, лицо серьёзное, как у завуча, и рыжий щенок Бублик, который пока не знает слова «нельзя»."}, {"md": "Вода в заводи чёрная, как чернила в непроливайке, и дна не видно даже у самого берега. С дальнего края торчит белая коряга с растопыренными сучьями, вылитая рука. Солнце лупит прямо в глаза. Я щурюсь и вижу, что под водой у коряги что-то блестит и подмигивает. Мне лично."}, {"md": "— Слабо до коряги? — Витька стаскивает футболку через голову и застревает в ней. — Кто не доплывёт, тот девчонка."}, {"md": "— Я девчонка, — говорит Ника. — И я не дура туда плыть."}, {"md": "Витька вылезает из футболки красный и, чтобы хоть кого-то победить, швыряет в воду палку. Бублик с визгом летит за ней прямо с камня. Его сразу разворачивает и тащит к коряге, над водой торчат одни уши. Ника кричит так, что с того берега взлетают вороны."}, {"md": "Бабка с первого этажа насчёт этой заводи была права. Почти во всех мирах, где я тогда полез в воду, меня потом так и не нашли.", "kind": "old"}, {"md": "Надо что-то делать, и прямо сейчас."}], "file": "T-01.md", "choices": [{"id": "A", "label": "«Мне не слабо!» — плыть с Витькой наперегонки к коряге", "fx": [["add", "ВОЛ", 10], ["add", "ТЕЛ", 5], ["add", "ЭМП", -5], ["set", "F_Т01", "СПОР"]], "outcomes": [{"to": "Т-02"}]}, {"id": "B", "label": "Прыгнуть за Бубликом", "fx": [["add", "ЭМП", 10], ["add", "ВОЛ", 5], ["add", "РАЗ", -5], ["add", "СВЯЗЬ_НИКА", 10], ["set", "F_Т01", "БУБЛИК"]], "outcomes": [{"to": "Т-02"}]}, {"id": "C", "label": "Нырнуть к тому, что блестит у коряги", "fx": [["add", "РАЗ", 10], ["add", "ДАР", 5], ["add", "ВОЛ", -5], ["set", "F_Т01", "ЧАСЫ"]], "outcomes": [{"to": "Т-02"}]}, {"id": "D", "label": "Бежать за взрослыми", "fx": [["add", "РАЗ", 5], ["add", "ЭМП", 5], ["add", "СВЯЗЬ_ВИТЬКА", 10], ["set", "F_Т01", "ДОЛГ"]], "outcomes": [{"to": "Т-02"}]}]}, "Т-02": {"id": "Т-02", "title": "Четыре минуты", "date": "28 июля 1996", "age": 7, "stage": "trunk", "photo": "bw", "photo_caption": "(кадр засвечен)", "photo_prompt": "completely black frame of an old black-and-white photo, only faint light rays from above as if seen from deep under water, grain, a single tiny glint, white border, scratched", "text": [{"md": "Я обгоняю Витьку на середине. Первый раз в жизни я обгоняю Витьку и даже успеваю этому обрадоваться. У свай вода становится тяжёлой, как мокрое одеяло, и кто-то спокойно, по-хозяйски берёт меня за ноги и тянет вниз. Последнее, что я вижу сверху, это Витькины пятки. Витька гребёт к берегу.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "СПОР"}}}, {"md": "Бублик визжит и лупит лапами по воде. Я хватаю его за шкирку и толкаю к берегу изо всех сил, как мяч на физре. Он выкарабкивается на камень и отряхивается прямо на Нику. А меня течение крутит, как щепку, и укладывает под корягу.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "БУБЛИК"}}}, {"md": "Под водой блестящее оказывается ближе, чем казалось. Я тянусь и хватаю что-то холодное и тяжёлое на железном браслете. Сжимаю кулак. И тут коряга цепляет меня за шорты, и наверх я уже не могу.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "ЧАСЫ"}}}, {"md": "Я успеваю пробежать по берегу шагов двадцать, и тут Ника кричит не своим голосом. Витька-дельфин полез за щенком и колотит руками у коряги, а голова у него уходит под воду. Как я оказался в воде, я не помню. Помню, как толкаю Витьку снизу в мокрую спину, а он хватается за корягу и лезет вверх прямо по мне, по голове, как по лестнице.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "ДОЛГ"}}}, {"md": "Коряга режет мне ладонь, длинно, от большого пальца до запястья. Я чувствую это даже сквозь холод. Потом холод куда-то девается."}, {"md": "Под водой темно и тепло, как под одеялом, когда играешь в прятки. И я тут не один. Никого не видно, но их много, как в автобусе в час пик, когда стоишь зажмурившись и всё равно знаешь, что кругом люди."}, {"md": "Сверху кто-то считает вслух тонким девчачьим голосом, сбивается и начинает снова."}, {"md": "Врачи потом говорили маме про переохлаждение и нырятельный рефлекс. Умные слова. Никаких рефлексов я под водой не помню. Помню, что было тесно.", "kind": "old"}, {"md": "Мне не страшно, честно. Только надо решить, что тут делать."}], "file": "T-02.md", "choices": [{"id": "A", "label": "Плыть на голос", "fx": [["add", "ВОЛ", 10], ["set", "F_Т02", "ЧЕЙ"]], "outcomes": [{"to": "Т-02б"}]}, {"id": "B", "label": "Слушать, что они шепчут", "fx": [["add", "ДАР", 10], ["set", "F_Т02", "ХОР"]], "outcomes": [{"to": "Т-02б"}]}, {"id": "C", "label": "Посмотреть вниз", "fx": [["add", "РАЗ", 10], ["set", "F_Т02", "ЛИЦО"]], "outcomes": [{"to": "Т-02б"}]}, {"id": "D", "label": "Позвать маму", "fx": [["add", "ЭМП", 10], ["add", "СВЯЗЬ_МАМА", 5], ["set", "F_Т02", "МАМА"]], "outcomes": [{"to": "Т-02б"}]}]}, "Т-02б": {"id": "Т-02б", "title": "Двести пятьдесят две", "date": "28 июля 1996", "age": 7, "stage": "trunk", "photo": "bw", "photo_caption": "Вторая городская, детское. Июль 1996", "photo_prompt": "old black-and-white photo, 1996, first-person view from a hospital bed, a soviet hospital ward with tall window and peeling paint, a woman's hand holding a child's bandaged hand, grain, white border", "text": [{"md": "Голос в темноте детский и дворовый.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "— Ты чей?", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "— Самохин, — говорю я, хотя рта у меня тут нет.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "— Ну так и вали к своим, — говорит голос и толкает меня в грудь. Больно, как мячом под дых.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "Я слушаю. Шёпот распадается на голоса, и все они говорят моим голосом, только один тоньше, другой ниже, а третий хрипит, как папа после смены. Они считают вместе с девчонкой сверху: сто девяносто, сто девяносто один. Им очень надо не сбиться.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ХОР"}}}, {"md": "Я смотрю вниз и вижу себя. Я лежу на песке белый, как та коряга, а надо мной на коленях стоит дед в мокрой тельняшке и давит мне на грудь двумя руками. Лицо у него как у папы, только старое и небритое. Он вытирает глаза ладонью, и на ладони у него шрам от большого пальца до запястья. Точно такой, какой мне только что сделала коряга.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЛИЦО"}}}, {"md": "Я зову маму, и темнота пахнет углём, мамиными волосами после смены. Кто-то кладёт мне ладонь на лоб, тёплую, шершавую и большую. Ладонь не мамина, но я всё равно не боюсь.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "МАМА"}}}, {"md": "Потом мне в грудь бьёт, как лошадь копытом, и я кашляю. Изо рта выливается полреки. Песок на зубах, солнце, небо слишком яркое. Кто-то поворачивает меня на бок, а вода всё идёт и идёт."}, {"md": "Когда я начинаю видеть, у воды уже никого нет. На ногах у меня мокрая брезентовая штормовка, а к тальнику идут следы босых ног, длинные, взрослые. Кусты ещё качаются."}, {"md": "Ника сидит рядом на корточках, губы синие, панамка в кулаке, и смотрит на меня как на чужого."}, {"md": "— Двести пятьдесят две, — говорит она. — Я считала. Двести пятьдесят две секунды."}, {"md": "Я разжимаю кулак. Поверх свежего пореза лежат мужские часы на железном браслете, мокрые, со звёздочкой на циферблате. Стрелки стоят на четырёх часах двенадцати минутах. Витька лезет посмотреть, и я сам не знаю почему опять сжимаю кулак.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "ЧАСЫ"}}}, {"md": "Витька стоит по колено в воде и трясётся весь, от макушки до пяток. Не ревёт, Витька никогда не ревёт. Потом говорит: «Ты чё, дурак?» — и садится прямо в воду.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "ДОЛГ"}}}, {"md": "Витька стоит в стороне и на меня не смотрит вообще, как будто если не смотреть, то ничего и не было.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "СПОР"}}}, {"md": "Мокрый Бублик, тощий, как крыса, лезет мне в лицо и вылизывает песок со щёк. Ника его не оттаскивает.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "БУБЛИК"}}}, {"md": "Скорая приезжает через полчаса: «буханка» с красным крестом и без одной фары. Мама влетает в неё прямо в рабочей робе, бьёт меня по щеке и тут же обнимает так, что я опять не могу дышать. В больнице мне зашивают ладонь, четыре шва. Врач в коридоре говорит маме «переохлаждение» и «повезло». Про деда в тельняшке милиция до вечера спрашивает у всего Рудничного. Такого никто не знает."}, {"md": "На другой день в палату приходит ещё один врач, не наш. Он в сером костюме, без халата, с портфелем, говорит, что из Томска, «по обмену опытом». Голос тихий, глаза усталые. Он берёт у меня кровь, две пробирки, хотя утром уже брали и медсестра Зина ругалась, что у меня вены как ниточки. Потом наклоняется совсем близко, чтобы Зина не слышала, и спрашивает:"}, {"md": "— Что ты там слышал?"}, {"md": "Я говорю, что они считали. Он сразу садится ко мне на кровать, хотя на кровать садиться нельзя, Зина за это гоняет. Сидит, весь белый. Я думаю, может, ему тоже будут ладонь зашивать.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ХОР"}}}, {"md": "Я не знаю, что сказать, и пожимаю плечами. Он кивает, как будто я всё-таки ответил, гладит меня по голове, как собаку, и уходит. Пробирки он кладёт в портфель.", "if": {"op": "cmp", "c": "!=", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ХОР"}}}, {"md": "Сорок лет было этому «доктору». Выглядел на все шестьдесят. В девяносто шестом все так выглядели.", "kind": "old"}, {"md": "Мне семь лет. Я утонул и вылез обратно. Откуда именно вылез, я пойму очень не сразу."}], "file": "T-02b.md", "next": "Т-03"}, "Т-03": {"id": "Т-03", "title": "Водяной", "date": "сентябрь 1996", "age": 7, "stage": "trunk", "photo": "bw", "photo_caption": "1 «А», школа № 41. 1 сентября 1996", "photo_prompt": "old black-and-white school photo, September 1996, first-person view from a 7-year-old holding gladioli with a bandaged palm, a crowd of first-graders in front of a soviet brick school, mothers in perms, grain, white border", "text": [{"md": "Первого сентября я иду в первый класс с гладиолусами и четырьмя швами на ладони. Гладиолусы мама выменяла у соседки на банку смородинового варенья, а швы мне сделали в больнице бесплатно."}, {"md": "На второй день меня уже зовут Водяным. Новости по Рудничному бегают быстрее, чем «Санта-Барбара» по телевизору. Про то, как Самохин-младший утонул и не утонул, знает даже буфетчица тётя Люба. Она даёт мне лишнюю булочку с повидлом, как больному."}, {"md": "В субботу из частного сектора под Красной Горкой приезжает бабушка. Привозит банку груздей и забирает с балкона штормовку, в которой меня принесли. Мама её постирала, а выкинуть так и не решилась. Бабушка долго держит штормовку на коленях и просит рассказать про деда, который меня вытащил. Я рассказываю: старый, в тельняшке, лицо как у папы."}, {"md": "— Тиша?.. — говорит бабушка очень тихо, и говорит не мне."}, {"md": "Тишей звали моего деда. Он умер, когда меня ещё не было, «на шахте», как у нас говорят про половину дедов в Кемерове. Мама уводит бабушку на кухню, и они там долго гремят чашками, хотя чай никто не наливает."}, {"md": "Вечером за ужином отец рассказывает про девяносто первый год, когда он с похмелья проспал смену, а клеть в тот день оборвалась."}, {"md": "— Мы, Самохины, везучие, — говорит он и стучит костяшками по столу."}, {"md": "— Пап, а ты чей? — спрашиваю я. Сам не знаю, зачем.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "Отец роняет кружку. Чай разливается по клеёнке, мама ругается и бежит за тряпкой, а отец сидит и смотрит на меня, пока она вытирает. Мне никто ничего не объясняет.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ЧЕЙ"}}}, {"md": "Клеть в девяносто первом оборвалась по-настоящему. Двое разбились. Отец потом каждый год пил за них на Покров, а за себя ни разу.", "kind": "old"}, {"md": "В школе есть Шмелёв из первого «Б», и Шмелёву очень нравится слово «Водяной». Он булькает мне вслед на каждой перемене и показывает руками, как я тону."}], "file": "T-03.md", "choices": [{"id": "A", "label": "Вмазать Шмелёву, и будь что будет", "fx": [["add", "ТЕЛ", 10], ["add", "ВОЛ", 5], ["add", "ЭМП", -5], ["set", "F_Т03", "ШРАМ"]], "outcomes": [{"to": "Т-04"}]}, {"id": "B", "label": "«Ну Водяной, и чё?» — сделать кличку своей", "fx": [["add", "ЭМП", 5], ["add", "ВОЛ", 5], ["set", "F_Т03", "ВОДЯНОЙ"]], "outcomes": [{"to": "Т-04"}]}, {"id": "C", "label": "Найти деда в тельняшке, который меня вытащил", "fx": [["add", "РАЗ", 5], ["add", "ВОЛ", 5], ["set", "F_Т03", "ЗАМЕТКА"]], "outcomes": [{"to": "Т-04"}]}, {"id": "D", "label": "Перестать разговаривать про воду. Вообще", "fx": [["add", "РАЗ", 5], ["add", "ЭМП", 5], ["set", "F_Т03", "ВОДОБОЯЗНЬ"]], "outcomes": [{"to": "Т-04"}]}]}, "Т-04": {"id": "Т-04", "title": "Рельсовая война", "date": "май 1998", "age": 9, "stage": "trunk", "photo": "bw", "photo_caption": "Сковородки. Прихожая, 1998", "photo_prompt": "old black-and-white amateur photo, 1998, first-person view of a narrow soviet apartment hallway with a tall stack of cast iron frying pans next to the coat rack, a baby stroller, worn linoleum, grain, white border", "text": [{"md": "Зарплату на шахте не дают седьмой месяц. В феврале родилась Сонька, красная и громкая, как пожарная машина, а в апреле отцу вместо денег выдали сорок чугунных сковородок. Они стоят в прихожей башней, и об неё все спотыкаются, кроме Соньки, которая пока не ходит."}, {"md": "По телевизору всё время говорят слово «бартер». Я думал, это фамилия какого-то министра."}, {"md": "В мае шахтёры садятся на рельсы. Под Анжеро-Судженском стоят поезда, по Транссибу ничего не ходит, у нас на ветке за Притомской тоже жгут костры. Отец приходит домой ночью, пахнет дымом и говорит маме:"}, {"md": "— Пока не отдадут, не встанем."}, {"md": "— А есть что будем? — спрашивает мама. — Сковородки?"}, {"md": "У Витьки свой план. На старой подстанции за гаражами, говорит он, валяется медный кабель, бесхозный, а приёмка на Строителей платит за медь живыми деньгами. А Нина Петровна, математичка, говорит, что задачу про два поезда в классе решил я один, и в субботу в городе областная олимпиада."}, {"md": "Суббота одна, а дел на неё четыре."}, {"md": "Через три месяца грохнул дефолт, и сковородки оказались самой твёрдой валютой в доме. Мама потом шутила, что это единственная зарплата, которую не съела инфляция.", "kind": "old"}], "file": "T-04.md", "choices": [{"id": "A", "label": "На рельсы, к отцу", "fx": [["add", "ВОЛ", 5], ["add", "ТЕЛ", 5], ["add", "СВЯЗЬ_ОТЕЦ", 10], ["set", "F_Т04", "РЕЛЬСЫ"]], "outcomes": [{"to": "Т-05"}]}, {"id": "B", "label": "С мамой на рынок, продавать сковородки", "fx": [["add", "ЭМП", 5], ["add", "РАЗ", 5], ["add", "СВЯЗЬ_МАМА", 5], ["set", "F_Т04", "РЫНОК"]], "outcomes": [{"to": "Т-05"}]}, {"id": "C", "label": "С Витькой за кабелем", "fx": [["add", "ТЕЛ", 10], ["add", "ВОЛ", 5], ["add", "РАЗ", -5], ["add", "СВЯЗЬ_ВИТЬКА", 10], ["set", "F_Т04", "ЦВЕТМЕТ"]], "outcomes": [{"to": "Т-05"}]}, {"id": "D", "label": "На олимпиаду с Ниной Петровной", "fx": [["add", "РАЗ", 5], ["add", "ВОЛ", 5], ["set", "F_Т04", "ОЛИМПИАДА"]], "outcomes": [{"to": "Т-05"}]}]}, "Т-05": {"id": "Т-05", "title": "Коробка", "date": "август 2000", "age": 11, "stage": "trunk", "photo": "bw", "photo_caption": "Т. С. и В. П., Томь, 1981", "photo_prompt": "old black-and-white photo from 1981, two men on a river bank, an older man in glasses and a hat resembling a miner, a thin young man holding a briefcase, wide Siberian river behind, faded, cracked emulsion, handwritten note on the white border", "text": [{"md": "В августе по телевизору все дни показывают подводную лодку «Курск». Мама смотрит новости и плачет, отец выключает телевизор и уходит курить на балкон. Я молчу. Им кажется, что там, под водой, в темноте и тесноте, страшнее всего на свете, а я знаю, что это не так. Только говорить про это нельзя, я уже понял."}, {"md": "Чтобы я не путался под ногами, мама отправляет меня разбирать сарай. Там лыжи без креплений, папины удочки, банки с гвоздями и коробка из-под югославских сапог, перемотанная синей изолентой. В коробке тетради в клеточку, исписанные формулами, одна фотография и конверт с сургучной печатью. На конверте написано «Коле». Коля — это папа."}, {"md": "На фотографии двое мужчин у реки. Один в очках и шляпе, похожий на папу, только старше. Второй молодой и худой, с портфелем. На обороте выцветшими чернилами: «Т. С. и В. П., Томь, 1981»."}, {"md": "Мама заглядывает в сарай, видит конверт и сразу его забирает. «Это папе, не трогай». Конверт уезжает в сервант, за хрусталь, туда, где лежат документы и деньги на чёрный день."}, {"md": "Ночью я не сплю и слышу стук, ровный, как метроном у нас на музыке. Откуда стучит, я так и не понимаю: то ли в батарее, то ли у меня в голове.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т02"}, "r": {"op": "lit", "v": "ХОР"}}}, {"md": "Сапоги из этой коробки мама носила восемь зим. Югославия тогда ещё умела делать сапоги.", "kind": "old"}], "file": "T-05.md", "choices": [{"id": "A", "label": "Читать тетради, пока никто не видит", "fx": [["add", "РАЗ", 5], ["add", "ДАР", 5], ["set", "F_Т05", "ТЕТРАДИ"]], "outcomes": [{"to": "Т-06"}]}, {"id": "B", "label": "Спросить маму, кто второй на фото", "fx": [["add", "ЭМП", 10], ["set", "F_Т05", "ФОТО"]], "outcomes": [{"to": "Т-06"}]}, {"id": "C", "label": "Отнести коробку старьёвщику на Советский: он даёт картриджи к «Сеге»", "fx": [["add", "ВОЛ", 10], ["add", "РАЗ", 5], ["add", "ТЕЛ", -5], ["set", "F_Т05", "ПРОДАЛ"]], "outcomes": [{"to": "Т-06"}]}, {"id": "D", "label": "Отдать коробку отцу", "fx": [["add", "ЭМП", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_ОТЕЦ", 10], ["set", "F_Т05", "СОЖЖЕНО"]], "outcomes": [{"to": "Т-06"}]}]}, "Т-06": {"id": "Т-06", "title": "Бакенщик", "date": "июль 2002", "age": 13, "stage": "trunk", "photo": "color", "photo_caption": "Витька, Ника и я. Лето 2002", "photo_prompt": "glossy color film print from 2002 with orange date stamp, first-person view, a 14-year-old boy smoking and squinting, a 13-year-old girl with braces holding a Strugatsky paperback, black still pond on a river bank, a white snag in the water, washed-out summer colors", "text": [{"md": "В июле опять приезжает Ника, первый раз с девяносто шестого. Я её сначала не узнаю. У неё брекеты, в рюкзаке Стругацкие, и Витьку она называет «Виктор», отчего Витька бесится так, что у него краснеют уши. Витьке четырнадцать, он курит «Яву» и сплёвывает сквозь зубы, как дядя Толя-таксист."}, {"md": "Бублик теперь мой. Ника тогда, в девяносто шестом, уехала без него, сказала, что он «выбрал». Он вымахал в рыжего лопоухого кобеля, при виде Ники орёт дурниной и катается на спине. Ника делает вид, что ей всё равно, и чешет ему пузо минут десять.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "БУБЛИК"}}}, {"md": "На третий день мы втроём идём на Чёрную заводь. Сами, без уговора, как будто это давно решено. Заводь такая же чёрная, коряга на месте. Мне тринадцать, и я изо всех сил делаю вид, что мне плевать."}, {"md": "Я шесть лет не заходил в воду глубже колена. В ванной сижу только с открытой дверью. Витька про это знает и молчит, и за это я ему многое прощаю.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т03"}, "r": {"op": "lit", "v": "ВОДОБОЯЗНЬ"}}}, {"md": "— Ну чё, Водяной, — говорит Витька, — реванш?"}, {"md": "Ника молчит. Она смотрит на корягу, а я смотрю на неё и думаю, что она, наверное, до сих пор помнит, до скольки досчитала."}, {"md": "Вверх по реке, за поворотом, торчит будка старого бакенщика. Бакенов на Томи давно никто не ставит, а бакенщик живёт там всё равно. Говорят, ему лет сто, и он видит всё, что творится на воде."}], "file": "T-06.md", "choices": [{"id": "A", "label": "Переплыть заводь. Вместе с Никой", "fx": [["add", "ТЕЛ", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_НИКА", 10], ["set", "F_Т06", "ПЕРЕПЛЫЛ"]], "outcomes": [{"to": "Т-07"}]}, {"id": "B", "label": "Отвести Нику в сторону и рассказать ей про темноту под водой", "fx": [["add", "ЭМП", 5], ["add", "ДАР", 5], ["add", "СВЯЗЬ_НИКА", 15], ["set", "F_Т06", "ТАЙНА_НИКИ"]], "outcomes": [{"to": "Т-07"}]}, {"id": "C", "label": "Поржать вместе с Витькой над «новосибирской»", "fx": [["add", "ТЕЛ", 10], ["add", "ВОЛ", 5], ["add", "ДАР", -5], ["add", "СВЯЗЬ_ВИТЬКА", 10], ["add", "СВЯЗЬ_НИКА", -10], ["set", "F_Т06", "ПАЦАНЫ"]], "outcomes": [{"to": "Т-07"}]}, {"id": "D", "label": "Сходить вверх по реке, к бакенщику", "fx": [["add", "РАЗ", 5], ["add", "ЭМП", 5], ["set", "F_Т06", "БАКЕНЩИК"]], "outcomes": [{"to": "Т-07"}]}]}, "Т-07": {"id": "Т-07", "title": "Лёд", "date": "декабрь 2003", "age": 14, "stage": "trunk", "photo": "color", "photo_caption": "«Девятка» дяди Толи. Зима 2003", "photo_prompt": "glossy color film print from 2003 with orange date stamp, night, first-person view through a frosted windshield of a VAZ-2109, a frozen wide river ahead lit by headlights, snow, steam, a boy's hand on the gear stick, orange street lamps far behind", "text": [{"md": "В декабре Витька угоняет у дяди Толи «девятку». Не насовсем, на вечер: дядя Толя в запое, ключи висят в прихожей на гвоздике, а на том берегу в клубе дискотека, и там будут девчонки из сто десятой школы. По мосту ехать нельзя, там гаишники. Значит, по льду, напрямик."}, {"md": "— Лёд встал, — говорит Витька. — Мужики на «Ниве» вчера проезжали. Сам видел."}, {"md": "На улице минус тридцать один. Вчера было минус девять. «Девятка» заводится с третьего раза и дышит паром, как корова. Из магнитолы орёт «Руки вверх». Витька сидит за рулём в отцовской ушанке и пытается найти первую передачу."}, {"md": "Я стою у пассажирской двери. Дверь открыта, Витька ждёт."}, {"md": "В затылке у меня становится холодно, как от сквозняка, хотя ветра нет. И перед глазами на секунду, как вспышка фотоаппарата, зелёная подсветка приборки, только почему-то под водой. Рыжие Витькины волосы плавают вверх.", "if": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 10}}}, {"md": "— Ну ты едешь или как? — орёт Витька. — Сейчас всё веселье без нас начнётся."}], "file": "T-07.md", "choices": [{"id": "A", "label": "Выдернуть ключи из замка", "fx": [["add", "ВОЛ", 10], ["add", "СВЯЗЬ_ВИТЬКА", -5], ["set", "F_Т07", "КЛЮЧИ"]], "outcomes": [{"to": "Т-08"}]}, {"id": "B", "label": "Сесть и ехать", "fx": [["add", "ТЕЛ", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_ВИТЬКА", 10], ["set", "F_Т07", "ЛЁД"]], "outcomes": [{"to": "Т-08"}]}, {"id": "C", "label": "Добежать до автомата и позвонить отцу", "fx": [["add", "РАЗ", 10], ["add", "ЭМП", 5], ["add", "ВОЛ", -5], ["add", "СВЯЗЬ_ВИТЬКА", -10], ["set", "F_Т07", "СДАЛ"]], "outcomes": [{"to": "Т-08"}]}, {"id": "D", "label": "Рассказать Витьке, что я сейчас увидел", "fx": [["add", "ДАР", 10], ["set", "F_Т07", "ВИДЕНИЕ"]], "outcomes": [{"to": "Т-08"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 10}}, "visible_src": "ДАР >= 10"}]}, "Т-08": {"id": "Т-08", "title": "Везунчик", "date": "апрель 2005", "age": 16, "stage": "trunk", "photo": "color", "photo_caption": "АБК «Глубокой». Третьи сутки", "photo_prompt": "glossy color film print from 2005 with orange date stamp, first-person view, crowd of women in puffy winter jackets outside a coal mine administrative building at dawn, a handwritten list of names on a board, a TV crew with a camera, grey April slush", "text": [{"md": "В апреле на «Глубокой» взрывается метан. Под землёй остаются двенадцать человек, и отец среди них."}, {"md": "Трое суток весь Рудничный стоит у АБК. Женщины в пуховиках, на доске листок со списком, написанным от руки, прокурор, телевизионщики из Новосибирска, которые всё время спрашивают, «что вы сейчас чувствуете». Мама не чувствует ничего, она стоит и держит Соньку за капюшон, чтобы та не убежала. Я стою рядом и считаю людей в списке. Двенадцать. Каждый час их всё ещё двенадцать."}, {"md": "Бублик три ночи воет во дворе, и никто из соседей на него не ругается.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "БУБЛИК"}}}, {"md": "На четвёртое утро клеть привозит наверх троих. Отец выходит вторым. Он серый, как штукатурка, и просит у кого-то закурить, хотя курит свои. Мама к нему не бежит. Она садится на корточки прямо в грязь и закрывает лицо руками."}, {"md": "Вечером, на кухне, когда мама с Сонькой уже спят, отец долго молчит, а потом говорит мне тихо:"}, {"md": "— Я там чуял, что умер, Андрюха. Три раза чуял. А потом стою у сбойки, живой, и дышу."}, {"md": "Бублик рычит на него из-под стола. Первый и последний раз в жизни.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т01"}, "r": {"op": "lit", "v": "БУБЛИК"}}}, {"md": "Больше он про это не говорит ни тогда, ни потом."}, {"md": "Из двенадцати подняли девятерых. Тех троих отец потом поминал на каждый Покров, вместе с двумя из девяносто первого.", "kind": "old"}, {"md": "Меня потом часто спрашивали, где я был эти трое суток. Я всегда отвечал коротко."}], "file": "T-08.md", "choices": [{"id": "A", "label": "«Таскал баллоны горноспасателям». Пролез к ним в первую же ночь, и меня не выгнали", "fx": [["add", "ТЕЛ", 5], ["add", "ВОЛ", 5], ["set", "F_Т08", "ПАЛЫЧ"]], "outcomes": [{"to": "Т-09"}]}, {"id": "B", "label": "«Дома». Мама, Сонька, суп, и ни одной слезы при них", "fx": [["add", "ЭМП", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_МАМА", 10], ["set", "F_Т08", "ДОМ"]], "outcomes": [{"to": "Т-09"}]}, {"id": "C", "label": "«На речке». Каждую ночь ходил на заводь разговаривать с водой", "fx": [["add", "ДАР", 5], ["add", "ЭМП", 5], ["set", "F_Т08", "ТОРГ"]], "outcomes": [{"to": "Т-09"}]}, {"id": "D", "label": "«Узнавал, почему рвануло». И всё рассказал журналистке из Новосибирска", "fx": [["add", "РАЗ", 10], ["add", "ВОЛ", 5], ["add", "ТЕЛ", -5], ["set", "F_Т08", "ДАТЧИКИ"]], "outcomes": [{"to": "Т-09"}]}]}, "Т-09": {"id": "Т-09", "title": "Проводы", "date": "июнь 2006", "age": 17, "stage": "trunk", "photo": "color", "photo_caption": "Проводы. Витька в центре", "photo_prompt": "glossy color film print from 2006 with orange date stamp, first-person view, a crowded courtyard farewell party for an army conscript, a shaved-head 18-year-old with a red face holding a glass, an accordion player, women crying, a table with salads in a soviet courtyard, evening light", "text": [{"md": "Витьке восемнадцать, и военкомат на Ноградской про него вспомнил. Повестка на двадцатое. Служат тогда ещё два года. Витька ходит по двору бритый наголо и делает вид, что ему смешно."}, {"md": "В ту же неделю приезжает Ника. У неё последнее школьное лето перед выпускным классом, и её отпустили к нам «в последний раз, потом поступать». Брекетов уже нет. Она подстриглась коротко, и на неё теперь оглядываются во дворе даже мужики у гаражей."}, {"md": "А Сварной, который держит приёмку металла на Строителей, а заодно половину Рудничного, говорит Витьке у ларька, что армию можно и «решить». Не бесплатно, конечно. Отдашь потом."}, {"md": "Отец в эти дни приходит со смены и сразу уходит в гараж. Сидит там допоздна. Мама говорит: «Иди посиди с ним, он сам не позовёт»."}, {"md": "Проводы назначены на субботу. Ника уезжает в воскресенье утром. Гараж никуда не денется, но отец сам не позовёт."}], "file": "T-09.md", "choices": [{"id": "A", "label": "Проводить Витьку как положено", "fx": [["add", "ЭМП", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_ВИТЬКА", 10], ["set", "F_Т09", "АРМИЯ"]], "outcomes": [{"to": "Т-10"}]}, {"id": "B", "label": "Помочь Витьке «решить» армию через Сварного", "fx": [["add", "ВОЛ", 5], ["add", "РАЗ", 5], ["add", "СВЯЗЬ_ВИТЬКА", 5], ["set", "F_Т09", "ДОЛГ_СВАРНОМУ"]], "outcomes": [{"to": "Т-10"}]}, {"id": "C", "label": "Уехать с Никой на дачу. Проводы как-нибудь без меня", "fx": [["add", "ЭМП", 10], ["add", "СВЯЗЬ_НИКА", 20], ["add", "СВЯЗЬ_ВИТЬКА", -10], ["set", "F_Т09", "НИКА"]], "outcomes": [{"to": "Т-10"}]}, {"id": "D", "label": "Пойти к отцу в гараж", "fx": [["add", "РАЗ", 5], ["add", "ВОЛ", 5], ["add", "СВЯЗЬ_ОТЕЦ", 10], ["set", "F_Т09", "ДВЕРЬ"]], "outcomes": [{"to": "Т-10"}]}]}, "Т-10": {"id": "Т-10", "title": "Рассвет", "date": "24 июня 2007, 04:12", "age": 18, "stage": "trunk", "photo": "digital", "photo_caption": "Выпускной. Набережная, 4 утра", "photo_prompt": "early digital camera photo from 2007, low resolution, first-person view, dawn over a wide Siberian river embankment, teenagers in suits and prom dresses with balloons, everyone holding up old Nokia phones, pale pink sky, a lone figure with a fishing rod on the far bank, slight motion blur", "text": [{"md": "Выпускной кончается на набережной, как у всех. Девчонки в платьях из «Ассорти», пацаны в пиджаках на вырост, шампанское «Советское» из горла, которое пронесли мимо классной в рукаве. Классная делает вид, что не видит. Ей тоже грустно."}, {"md": "Галина Ивановна, наша астрономичка, ходит между нами в шали и раздаёт напутствия. Мне она говорит то же, что на последнем уроке говорила всему классу:"}, {"md": "— Комета Галлея вернётся двадцать восьмого июля шестьдесят первого. Вам будет по семьдесят два. Доживёте — посмотрите."}, {"md": "Все ржут. Семьдесят два — это никогда."}, {"md": "Витька тоже тут, хотя он из другого выпуска. Пришёл «проводить», в кожанке Сварного, и угощает всех «Парламентом». Мы с ним теперь должны Сварному на двоих, и это висит над нами, как туча над Кировским районом.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т09"}, "r": {"op": "lit", "v": "ДОЛГ_СВАРНОМУ"}}}, {"md": "Витька служит под Читой. Месяц назад прислал письмо на полстраницы, из которых половину зачеркнул военный цензор, а может, сам Витька.", "if": {"op": "cmp", "c": "!=", "l": {"op": "var", "n": "F_Т09"}, "r": {"op": "lit", "v": "ДОЛГ_СВАРНОМУ"}}}, {"md": "Небо над Томью розовеет. И тут у всех в классе одновременно пищат «Нокии»: у кого-то будильник, у кого-то эсэмэски «поздравляю». Я смотрю на свою «3310». Четыре ноль-ноль. Нет, четыре двенадцать. Я моргаю, и снова четыре двенадцать."}, {"md": "Эсэмэска от Ники, из Новосибирска: «Не спишь? Я тоже. Смотрю на реку, у нас она другая». Я не отвечаю минут десять, потому что не знаю как.", "if": {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т09"}, "r": {"op": "lit", "v": "НИКА"}}}, {"md": "На том берегу кто-то стоит с удочкой. Или это куст. Пока я присматриваюсь, солнце вылезает из-за Притомского, и того берега становится не видно."}, {"md": "Восемнадцать лет. Самое время решить, кем быть. Я решил. В одном из миров решил правильно, только не знаю, в каком.", "kind": "old"}], "file": "T-10.md", "choices": [{"id": "A", "label": "«Как батя». Горный техникум и «Глубокая»", "fx": [["set", "F_ПУТЬ", "ЛАМПА"]], "outcomes": [{"to": "Д-00"}]}, {"id": "B", "label": "Поступать на физфак в Томск", "fx": [["set", "F_ПУТЬ", "ПРОТОКОЛ"]], "outcomes": [{"to": "Ж-00"}], "visible": {"op": "or", "a": [{"op": "cmp", "c": ">=", "l": {"op": "var", "n": "РАЗ"}, "r": {"op": "num", "v": 40}}, {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т05"}, "r": {"op": "lit", "v": "ТЕТРАДИ"}}, {"op": "cmp", "c": "==", "l": {"op": "var", "n": "F_Т04"}, "r": {"op": "lit", "v": "ОЛИМПИАДА"}}]}, "visible_src": "РАЗ >= 40 || F_Т05 == ТЕТРАДИ || F_Т04 == ОЛИМПИАДА"}, {"id": "C", "label": "Рабочим в геологическую партию, в Горную Шорию", "fx": [["set", "F_ПУТЬ", "ПАРТИЯ"]], "outcomes": [{"to": "Ж-00"}], "visible": {"op": "or", "a": [{"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ТЕЛ"}, "r": {"op": "num", "v": 35}}, {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ВОЛ"}, "r": {"op": "num", "v": 40}}]}, "visible_src": "ТЕЛ >= 35 || ВОЛ >= 40"}, {"id": "D", "label": "Сварной звал: «Деньги нужны? Есть работа»", "fx": [["set", "F_ПУТЬ", "БАРАБАН"]], "outcomes": [{"to": "Ж-00"}]}, {"id": "E", "label": "Куда угодно, лишь бы отсюда", "fx": [["set", "F_ПУТЬ", "ТЁПЛАЯ_ВОДА"]], "outcomes": [{"to": "Ж-00"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ВОЛ"}, "r": {"op": "num", "v": 35}}, "visible_src": "ВОЛ >= 35"}, {"id": "F", "label": "Голоса в голове стали громче людей", "fx": [["set", "F_ПУТЬ", "ХОР"]], "outcomes": [{"to": "Ж-00"}], "visible": {"op": "cmp", "c": ">=", "l": {"op": "var", "n": "ДАР"}, "r": {"op": "num", "v": 25}}, "visible_src": "ДАР >= 25"}, {"id": "G", "label": "Остаться. Работа, свадьба, дача. Просто жить", "fx": [["set", "F_ПУТЬ", "СЕМЬЯ"]], "outcomes": [{"to": "Ж-00"}]}]}}, "deaths": {"✝Д-01.A": {"id": "✝Д-01.A", "title": "Чёрная вода", "date": "14 ноября 2009, 04:12", "age": 20, "stihia": "ПОРОДА", "epitaph": "20 лет. Шахта «Глубокая», лава 3. Бежал.", "mourner": "Таня-ламповщица утром увидела на стойке его лампу. Одну, никем не взятую.", "text": [{"md": "Я бегу. Шорох за спиной превращается в рёв, и меня бьёт в спину чёрной волной, тяжёлой, как мокрый цемент. Уголь течёт по-настоящему, как вода. Он заливает ноги, потом колени, потом грудь, и до меня доходит, что я тону, как тогда в заводи. Только эта вода наверх не пускает совсем."}, {"md": "Успеваю подумать: «Ну ёлки, опять». Потом пахнет мамиными волосами."}], "file": "X-D01A.md", "awake": [{"md": "…и я стою в забое. Пласт вздыхает. Михалыч замолкает на полуслове."}, {"md": "Пошевелиться я не могу, потому что только что умер и всё помню: уголь во рту, тяжесть на груди, темноту. Минута, которой ещё не было, у меня уже позади."}, {"md": "Сердце колотится в рёбра. Во рту сухо, но на зубах хрустит угольная крошка. Михалыч смотрит на меня как на психа. Шорох впереди нарастает."}, {"md": "А за стенкой забоя, где нет ничего, кроме угля, плачет женщина."}]}, "✝Д-01.B": {"id": "✝Д-01.B", "title": "Чёрная вода", "date": "14 ноября 2009, 04:12", "age": 20, "stihia": "ПОРОДА", "epitaph": "20 лет. Шахта «Глубокая», лава 3. Лёг, как учили.", "mourner": "Отец поднялся на-гора последним и три дня ни с кем не разговаривал.", "text": [{"md": "Я падаю на почву лицом в мокрую крошку, руки на затылок, всё как учили на курсах. Уголь приходит сверху и прижимает к земле, спокойно и по-хозяйски, и становится тихо. Вдохнуть не могу, пальцем пошевелить не могу. Под щекой холодно, и я вспоминаю, что меня уже так держали. В тёплой темноте, где было тесно от голосов."}, {"md": "Голоса здесь, совсем рядом, и, похоже, мне рады."}], "file": "X-D01B.md", "awake": [{"md": "…и я стою в забое. Пласт вздыхает. Михалыч замолкает на полуслове."}, {"md": "Я только что лежал под углём и не мог вдохнуть. Сны так не болят. В ушах ещё звенит та тишина."}, {"md": "Шорох впереди нарастает, а я откуда-то точно знаю, что ложиться уже пробовал."}]}, "✝Д-01.C": {"id": "✝Д-01.C", "title": "Чёрная вода", "date": "14 ноября 2009, 04:12", "age": 20, "stihia": "ПОРОДА", "epitaph": "20 лет. Шахта «Глубокая», лава 3. Держался.", "mourner": "Мама полгода ставила на стол лишнюю тарелку и спохватывалась.", "text": [{"md": "Я обнимаю стойку крепи обеими руками, как в детстве мамину ногу в очереди за сахаром. Стойка вздрагивает, потом гнётся, медленно, как пластилиновая, и стонет. Я и не знал, что железо так умеет. Кровля садится на меня неторопливо, как старик на лавку. Последнее, что я вижу в свете лампы, это свои руки на стойке и шрам на ладони."}], "file": "X-D01C.md", "awake": [{"md": "…и я стою в забое. Пласт вздыхает. Михалыч замолкает на полуслове."}, {"md": "Смотрю на ладонь. Шрам на месте, руки целые. А плечи ещё помнят, как на них садилась кровля."}, {"md": "Я не псих. Я это знаю так же точно, как знаю, что сейчас пойдёт уголь."}]}, "✝Д-02.A": {"id": "✝Д-02.A", "title": "Метан", "date": "3 марта 2012, 04:12", "age": 23, "stihia": "ВОЗДУХ", "epitaph": "23 года. Главный штрек, пятисотый метр. Бежал к стволу.", "mourner": "Серёга дошёл. Потом каждую годовщину пил, и на восьмой рюмке называл его братом.", "text": [{"md": "Я бегу. Восемьсот метров для меня ерунда, наверху я пробегаю их за три минуты. Здесь каждый вдох обдирает горло, как горячий песок. На четырёхсотом метре колени перестают слушаться. На пятисотом я обнаруживаю, что лежу, а как падал, не помню. Фонарь светит в кровлю. Очень хочется спать, и мама почему-то рассказывает про свои волосы, которые пахнут углём…"}], "file": "X-D02A.md", "awake": [{"md": "…и я стою в лаве. Датчик пищит. Серёга матерится в сорока метрах позади."}, {"md": "Лёгкие ещё горят. Холодный пол под щекой, луч фонаря в кровле, пятисотый метр. Восемьсот метров для меня, выходит, много."}]}, "✝Д-02.B": {"id": "✝Д-02.B", "title": "Метан", "date": "3 марта 2012, 04:12", "age": 23, "stihia": "ВОЗДУХ", "epitaph": "23 года. Старая сбойка. Сделал всё по инструкции, только по чужой.", "mourner": "Нашли через двое суток. Мама опознала его по шраму на ладони.", "text": [{"md": "Самоспасатель шипит, во рту резиновый привкус. Я сижу в сбойке и жду, как положено. Только сбойка тупиковая. Воздух в ней стоит, как в трёхлитровой банке, и газ натекает сюда первым, тихо, как кот на кухню. Доходит до меня это, когда руки перестают слушаться и самоспасатель начинает казаться лишним и тяжёлым."}, {"md": "Я его снимаю. Мне вдруг хорошо и спокойно, и это последнее, что я думаю."}], "file": "X-D02B.md", "awake": [{"md": "…и я стою в лаве. Датчик пищит."}, {"md": "Сбойка была тупиковая. Кто учил инструкции, тот бы знал. А я сидел и ждал по правилам, пока меня отравят."}]}, "✝Д-02.C": {"id": "✝Д-02.C", "title": "Метан", "date": "3 марта 2012, 04:12", "age": 23, "stihia": "ВОЗДУХ", "epitaph": "23 года. Лава 5. Вернулся за напарником.", "mourner": "Серёгу вытащили живым. Через год он назвал сына его именем.", "text": [{"md": "Я иду назад на его фонарь. Серёга сидит у конвейера и держится за ногу: подвернул, когда прыгал через став. Я подставляю плечо. Мы идём, и он тяжёлый, как мешок с углём, и с каждым шагом тяжелее. Я его не роняю, просто в какой-то момент ложусь рядом, потому что кончился воздух."}], "file": "X-D02C.md", "awake": [{"md": "…и я стою в лаве. Серёга матерится в сорока метрах позади."}, {"md": "Я его не донёс. Сил не хватило, и плечо до сих пор чувствует, сколько он весит."}]}}};
